import sys, os, re, json, math, bisect
from datetime import datetime

QS = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
          "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
CONV = {
    "temp": {"degC": lambda v: v, "degF": lambda v: (v - 32) * 5 / 9, "K": lambda v: v - 273.15},
    "rh": {"pct": lambda v: v, "frac": lambda v: v * 100},
    "pres": {"hPa": lambda v: v, "kPa": lambda v: v * 10,
             "inHg": lambda v: v * 33.8638866667, "mmHg": lambda v: v * 1.33322387415},
    "wspd": {"ms": lambda v: v, "kmh": lambda v: v / 3.6,
             "kn": lambda v: v * 1852 / 3600, "mph": lambda v: v * 0.44704},
    "wdir": {"deg": lambda v: v},
    "rain": {"mm": lambda v: v},
}
DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
MISSING = re.compile(r"^-9999(\.0*)?$")


def ptime(s):
    s = s.strip().replace("T", " ")
    d = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
    return int((d - datetime(1970, 1, 1)).total_seconds())


def ptz(s):
    s = s.strip()
    if s == "Z":
        return 0
    sign = -1 if s[0] == "-" else 1
    h, m = s[1:].split(":")
    return sign * (int(h) * 3600 + int(m) * 60)


def converter(q, unit):
    if unit.startswith("tips:") and q == "rain":
        s = float(unit[5:])
        return lambda v: v * s
    return CONV[q].get(unit)


def parse_value(f):
    f = f.strip()
    if f == "" or f == "---" or f.lower() == "nan" or MISSING.match(f):
        return None
    try:
        v = float(f)
    except ValueError:
        return None
    if math.isnan(v) or math.isinf(v):
        return None
    return v


def read_file(path):
    with open(path, "rb") as fh:
        text = fh.read().decode("utf-8-sig")
    hdr = {}
    cols = None
    units = {}
    rows = []   # (instant, {q: value})
    syncs = []  # (instant, ref)
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if line[0] == "#":
            m = DIRECTIVE.match(line)
            if not m:
                continue
            k, v = m.group(1), m.group(2).strip()
            if k in ("station", "upload", "interval", "tz"):
                hdr[k] = v
            elif k == "columns":
                cols = [c.strip() for c in v.split(",")]
            elif k == "units":
                for tok in v.split():
                    if "=" in tok:
                        q, u = tok.split("=", 1)
                        units[q] = u
            elif k == "sync":
                parts = {}
                for tok in v.split():
                    if "=" in tok:
                        a, b = tok.split("=", 1)
                        parts[a] = b
                if "logger" in parts and "ref" in parts:
                    tz = ptz(hdr["tz"])
                    li = ptime(parts["logger"]) - tz
                    ref = ptime(parts["ref"].rstrip("Z"))
                    syncs.append((li, ref))
            continue
        if cols is None or "tz" not in hdr:
            continue
        fields = [f.strip() for f in line.split(",")]
        vals = {}
        t = None
        for c, f in zip(cols, fields):
            if c == "time":
                t = ptime(f)
            elif c in RANGES:
                v = parse_value(f)
                if v is not None:
                    cv = converter(c, units.get(c, {"temp": "degC", "rh": "pct", "pres": "hPa",
                                                    "wspd": "ms", "wdir": "deg", "rain": "mm"}[c]))
                    if cv is not None:
                        v = cv(v)
                        lo, hi = RANGES[c]
                        if lo <= v <= hi:
                            vals[c] = v
        if t is None:
            continue
        rows.append((t - ptz(hdr["tz"]), vals))
    return hdr, rows, [(li, ref - li) for li, ref in syncs]


def main(indir, outfile):
    stations = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith(".log") or not os.path.isfile(p):
            continue
        hdr, rows, syncs = read_file(p)
        if "station" not in hdr:
            continue
        up = int(hdr.get("upload", 0))
        st = stations.setdefault(hdr["station"], {"interval": None, "rows": {}, "sync": {}})
        if "interval" in hdr:
            st["interval"] = int(float(hdr["interval"]))
        for inst, vals in rows:
            cur = st["rows"].get(inst)
            if cur is None or up > cur[0]:
                st["rows"][inst] = (up, vals)
        for inst, off in syncs:
            cur = st["sync"].get(inst)
            if cur is None or up > cur[0]:
                st["sync"][inst] = (up, off)
    result = []
    for sid in sorted(stations):
        st = stations[sid]
        if not st["rows"]:
            continue
        interval = st["interval"]
        sp = sorted((t, o) for t, (u, o) in st["sync"].items())
        ts = [t for t, _ in sp]

        def offset(t):
            if not sp:
                return 0
            i = bisect.bisect_left(ts, t)
            if i < len(ts) and ts[i] == t:
                return sp[i][1]
            if i == 0:
                return sp[0][1]
            if i == len(ts):
                return sp[-1][1]
            t1, o1 = sp[i - 1]
            t2, o2 = sp[i]
            return (o1 * (t2 - t1) + (o2 - o1) * (t - t1)) // (t2 - t1)

        recs = sorted(((inst + offset(inst), vals) for inst, (u, vals) in st["rows"].items()),
                      key=lambda r: r[0])
        hour = lambda c: -((-c) // 3600) * 3600
        first, last = hour(recs[0][0]), hour(recs[-1][0])
        data = {}
        prev = None
        for c, vals in recs:
            h = hour(c)
            d = data.setdefault(h, {"n": dict.fromkeys(QS, 0), "sum": dict.fromkeys(QS, 0.0),
                                    "sx": 0.0, "sy": 0.0, "nv": 0, "inc": 0.0})
            for q, v in vals.items():
                d["n"][q] += 1
                d["sum"][q] += v
            if "rain" in vals:
                r = vals["rain"]
                if prev is not None and (c - prev[0]) * 2 <= 5 * interval:
                    d["inc"] += r - prev[1] if r >= prev[1] else r
                prev = (c, r)
            if "wdir" in vals and vals.get("wspd", 0) > 0:
                a = math.radians(vals["wdir"])
                d["sx"] += math.sin(a)
                d["sy"] += math.cos(a)
                d["nv"] += 1
        expected = 3600 / interval
        hours = []
        for h in range(first, last + 1, 3600):
            d = data.get(h)
            e = {"hour": datetime.utcfromtimestamp(h).strftime("%Y-%m-%dT%H:00:00Z")}
            for q in QS:
                n = d["n"][q] if d else 0
                val = None
                if d and n * 4 >= expected * 3:
                    if q in ("temp", "rh", "pres", "wspd"):
                        val = round(d["sum"][q] / n, 2)
                    elif q == "rain":
                        val = round(d["inc"], 2)
                    elif d["nv"] > 0:
                        val = round(math.degrees(math.atan2(d["sx"], d["sy"])) % 360, 2)
                        if val >= 360:
                            val = 0.0
                    if val is not None:
                        val += 0.0
                e[q] = {"value": val, "n": n}
            hours.append(e)
        result.append({"station": sid, "interval_s": interval, "hours": hours})
    with open(outfile, "w") as fh:
        json.dump({"stations": result}, fh)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
